CREATE TABLE IF NOT EXISTS team_penalties (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NOT NULL,points_delta INT NOT NULL DEFAULT 0,penalty_type VARCHAR(50) NOT NULL,reason TEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS player_statistics (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NOT NULL,goals INT NOT NULL DEFAULT 0,own_goals INT NOT NULL DEFAULT 0,assists INT NOT NULL DEFAULT 0,yellow_cards INT NOT NULL DEFAULT 0,red_cards INT NOT NULL DEFAULT 0,appearances INT NOT NULL DEFAULT 0,starts INT NOT NULL DEFAULT 0,sub_appearances INT NOT NULL DEFAULT 0,penalties_scored INT NOT NULL DEFAULT 0,penalties_missed INT NOT NULL DEFAULT 0,updated_at DATETIME NOT NULL,UNIQUE KEY tournament_person(tournament_id,person_id),FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(person_id) REFERENCES people(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
